                        /// City, district, suburb, town, or village.
                        public var city: String?
                        /// Two-letter country code (ISO 3166-1 alpha-2).
                        public var country: String?
                        /// Address line 1, such as the street, PO Box, or company name.
                        public var line1: String?
                        /// Address line 2, such as the apartment, suite, unit, or building.
                        public var line2: String?
                        /// ZIP or postal code.
                        public var postalCode: String?
                        /// State, county, province, or region (ISO 3166-2).
                        public var state: String?

                        private enum CodingKeys: String, CodingKey {
                            case city
                            case country
                            case line1
                            case line2
                            case postalCode
                            case state
                        }

                        public init(
                            city: String? = nil,
                            country: String? = nil,
                            line1: String? = nil,
                            line2: String? = nil,
                            postalCode: String? = nil,
                            state: String? = nil
                        ) {
                            self.city = city
                            self.country = country
                            self.line1 = line1
                            self.line2 = line2
                            self.postalCode = postalCode
                            self.state = state
                        }
                    }
                }
            }

            /// Shipping details attached to this payment.
            public struct ShippingDetails: Codable, Hashable, Sendable {
                public var address: Address?
                /// Shipping name.
                public var name: String?
                /// Shipping phone number.
                public var phone: String?

                private enum CodingKeys: String, CodingKey {
                    case address
                    case name
                    case phone
                }

                public init(
                    address: Address? = nil,
                    name: String? = nil,
                    phone: String? = nil
                ) {
                    self.address = address
                    self.name = name
                    self.phone = phone
                }

                /// Address data.
                public struct Address: Codable, Hashable, Sendable {
                    /// City, district, suburb, town, or village.
                    public var city: String?
                    /// Two-letter country code (ISO 3166-1 alpha-2).
                    public var country: String?
                    /// Address line 1, such as the street, PO Box, or company name.
                    public var line1: String?
                    /// Address line 2, such as the apartment, suite, unit, or building.
                    public var line2: String?
                    /// ZIP or postal code.
                    public var postalCode: String?
                    /// State, county, province, or region (ISO 3166-2).
                    public var state: String?

                    private enum CodingKeys: String, CodingKey {
                        case city
                        case country
                        case line1
                        case line2
                        case postalCode
                        case state
                    }

                    public init(
                        city: String? = nil,
                        country: String? = nil,
                        line1: String? = nil,
                        line2: String? = nil,
                        postalCode: String? = nil,
                        state: String? = nil
                    ) {
                        self.city = city
                        self.country = country
                        self.line1 = line1
                        self.line2 = line2
                        self.postalCode = postalCode
                        self.state = state
                    }
                }
            }
        }

        /// Collection of signals for this payment evaluation.
        public struct Signals: Codable, Hashable, Sendable {
            public var fraudulentPayment: FraudulentPayment?

            private enum CodingKeys: String, CodingKey {
                case fraudulentPayment
            }

            public init(
                fraudulentPayment: FraudulentPayment? = nil
            ) {
                self.fraudulentPayment = fraudulentPayment
            }

            /// A payment evaluation signal with evaluated_at, risk_level, and score fields.
            public struct FraudulentPayment: Codable, Hashable, Sendable {
                /// The time when this signal was evaluated.
                public var evaluatedAt: Date?
                /// Risk level of this signal, based on the score.
                public var riskLevel: RiskLevel?
                /// Score for this signal.
                public var score: Double?

                private enum CodingKeys: String, CodingKey {
                    case evaluatedAt
                    case riskLevel
                    case score
                }

                public init(
                    evaluatedAt: Date? = nil,
                    riskLevel: RiskLevel? = nil,
                    score: Double? = nil
                ) {
                    self.evaluatedAt = evaluatedAt
                    self.riskLevel = riskLevel
                    self.score = score
                }

                /// Risk level of this signal, based on the score.
                public enum RiskLevel: String, Codable, Hashable, Sendable {
                    case elevated
                    case highest
                    case low
                    case normal
                    case notAssessed = "not_assessed"
                    case unknown
                }
            }
        }
    }
